import React from "react";
import "./SpendingPriority.css";
import Navbar from "./Navbar";

function SpendingPriority({ data, setData, onNext, onBack }) {

  const selected = data.priorities || [];

  const categories = [
    "Food & Groceries",
    "Shopping",
    "Bills",
    "Health",
    "Entertainment",
    "Transport",
  ];

  const toggleSelect = (item) => {
    let updated;

    if (selected.includes(item)) {
      updated = selected.filter(i => i !== item);
    } else {
      updated = [...selected, item];
    }

    setData({ ...data, priorities: updated });
  };

  return (
    <>
      <Navbar 
  title="Spending Priority" 
  onBack={onBack} 
  nextLabel="Budget Limits"
/>

      <div className="spending-page">
        <div className="spending-wrapper">

          <div className="spending-header">
            <h1>Set Your Spending Priorities</h1>
            <p>Select categories that matter most to you</p>
          </div>

          <div className="spending-grid">
            {categories.map((item, index) => (
              <div
                key={index}
                className={`spending-card ${selected.includes(item) ? "active" : ""}`}
                onClick={() => toggleSelect(item)}
              >
                {item}
              </div>
            ))}
          </div>

          <div className="spending-action">
            <button onClick={onNext}>Continue</button>
          </div>

        </div>
      </div>
    </>
  );
}

export default SpendingPriority;
